bounded_host_request.command:
set -euo pipefail
name=gace-createvdobot-videobot-poll-1
test "$(docker inspect -f '{{.State.Running}}' "$name" 2>/dev/null)" = true || exit 61
live="$(docker inspect -f '{{.Image}}' "$name")"
tag="$(docker image inspect -f '{{.Id}}' create-videobot:local-poll)"
test "$live" = "$tag" || exit 62
docker logs --tail 120 "$name" 2>&1 | grep -q '^CREATOR_DM_POLL_READY=PASS$' || exit 63
docker exec -i "$name" node --input-type=module - <<'NODE'
import pg from 'pg';
import {readFileSync} from 'node:fs';
import {createStickerSalesFlow} from './src/telegram/stickerSales.mjs';
const e=process.env;
const pool=new pg.Pool({host:e.VIDEOBOT_DB_HOST,database:e.VIDEOBOT_DB_NAME,
 user:e.VIDEOBOT_DB_USER,password:readFileSync(e.VIDEOBOT_DB_PASSWORD_FILE,'utf8').trim(),
 max:1,connectionTimeoutMillis:5000});
try{
 const cols=await pool.query(`SELECT COUNT(*)::int AS n FROM information_schema.columns
 WHERE table_schema='public' AND
 ((table_name='videobot_sticker_products' AND column_name IN
 ('management_fee_bps','fee_policy_id','fee_terms_accepted_at'))
 OR (table_name='videobot_sticker_orders' AND column_name IN
 ('management_fee_bps','fee_policy_id','management_fee_tenths','creator_share_tenths')))`);
 if(cols.rows?.[0]?.n!==7)throw Error('FEE_SCHEMA_INCOMPLETE');
 const db=await pool.query(`SELECT COUNT(*)::int AS total,
 COUNT(*) FILTER (WHERE management_fee_bps=3000 AND fee_policy_id='sticker-admin-30-20261113'
 AND management_fee_tenths=price_stars*3 AND creator_share_tenths=price_stars*7)::int AS verified,
 COUNT(*) FILTER (WHERE management_fee_bps IS NULL)::int AS legacy
 FROM videobot_sticker_orders`);
 if(!db.rows?.length||db.rows[0].total!==db.rows[0].verified+db.rows[0].legacy)
  throw Error('FEE_ORDER_SNAPSHOT_INVALID');
 let s={revision:0,screen:'home',screenMessageId:null},shown;
 const sessionStore={
  read:async()=>structuredClone(s),
  write:async(_id,rev,next)=>{if(rev!==s.revision)throw Error('REVISION');s=structuredClone(next);},
  setScreen:async(_id,rev,msg)=>{if(rev!==s.revision)throw Error('SCREEN_REVISION');s.screenMessageId=msg;}
 };
 const flow=createStickerSalesFlow({
  api:async()=>true,sessionStore,screenTransport:{show:async(_id,_prev,panel)=>{shown=panel;return {messageId:10};}},
  salesStore:{reserveOrder:async()=>{},capturePayment:async()=>{}},
  packInventory:{getOwnedPack:async()=>({pack_name:'ci_safe_mock',title:'価格確認',kind:'regular'})},
  publishSnapshot:async()=>{throw Error('NO_PUBLISH');}
 });
 await flow.beginSell({ownerId:1,packName:'ci_safe_mock'});
 const buttons=shown.reply_markup.inline_keyboard.flat().map(b=>b.text);
 if(!['50','100','300','500','1000','自分で決める'].every(t=>buttons.includes(t)))
  throw Error('FEE_PRESET_BUTTONS_MISSING');
 await flow.handle({callback_query:{id:'offline-only',from:{id:1},message:{
  chat:{type:'private',id:1},message_id:10},data:'sale:price:300|r1'}});
 if(s.screen!=='sticker_sale_confirm'||s.stickerSale.price!==300||
 !shown.text.includes('管理費90 Stars')||!shown.text.includes('投稿者分210 Stars'))
  throw Error('FEE_PREVIEW_INCORRECT');
 process.stdout.write('STK03_LIVE_IMAGE_PRESET_6=PASS\n');
 process.stdout.write('STK03_LIVE_IMAGE_FEE_30_70=PASS\n');
 process.stdout.write('STK03_DB_MIGRATION_014=PASS\n');
 process.stdout.write('STK03_DB_ORDER_SNAPSHOT=PASS\n');
}finally{await pool.end();}
NODE
